I18nLocaleService:
class {
        constructor() {
            this.lang = 'zh';
        }
        getLocale() {
            // 从localStorage读取缓存
            const cachedLang = localStorage.getItem('i18n-lang');
            if (cachedLang) {
                this.lang = cachedLang;
            }
            return this.lang === 'en' ? en_1.en : zh_1.zh;
        }
        get(key, params) {
            const pack = this.getLocale();
            const val = key.split('.').reduce((o, k) => (o ? o[k] : undefined), pack);
            let s = typeof val === 'string' ? val : '';
            if (params) {
                for (const [k, v] of Object.entries(params)) {
                    s = s.replace(new RegExp(`\\{${k}\\}`, 'g'), String(v));
                }
            }
            return s;
        }
        setLang(code) {
            this.lang = code;
            // 缓存到localStorage
            localStorage.setItem('i18n-lang', code);
            window.location.reload();
        }
    }
